  ('f9-business', 'f9', 'Business bundle', 1, 1, 0, 0, NULL, NULL, 0, 50, 'https://faq.flyfrontier.com/help/what-is-the-difference-between-economy-premium-and-business-bundles', 'Frontier – bundle inclusions', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'Frontier-operated US domestic flights, one way per passenger, ordinary baggage. Any bundle or bag purchase is separate from the base fare.', 'USD', 'verified', 'One personal item and one carry-on are included. The first two checked bags each have a 50 lb allowance. Further bags are priced for the itinerary and use the standard weight limit.', datetime('now')),
  ('wn-wanna', 'wn', 'Wanna Get Away', 1, 1, 45, 55, 150, NULL, 0, NULL, 'https://www.southwest.com/html/customer-service/travel-fees.html', 'Southwest Airlines - Travel fees', NULL, '2026-11-04T18:09:02.088Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'The seed modelled two free checked bags. For itineraries ticketed on or after 18 April 2026 the Basic Fare charges $45 for the 1st bag and $55 for the 2nd, so first_checked_fee 0->$45 and second_checked_fee 0->$55. 3rd and each additional bag $150. A carry-on bag and a personal item remain included.', datetime('now')),
  ('as-saver', 'as', 'Saver', 1, 1, 45, 55, 200, NULL, 0, NULL, 'https://www.alaskaair.com/content/travel-info/baggage/checked-bags', 'Alaska Airlines - Checked bags', NULL, '2026-11-04T18:05:49.760Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Saver airport fees for tickets ticketed on or after 10 April 2026: 1st bag $35->$45, 2nd bag $45->$55, 3rd bag $200, 4th and each additional bag $200. A carry-on bag and a personal item are included.', datetime('now')),
  ('as-main', 'as', 'Main', 1, 1, 45, 55, 200, NULL, 0, NULL, 'https://www.alaskaair.com/content/travel-info/baggage/checked-bags', 'Alaska Airlines - Checked bags', NULL, '2026-11-04T18:05:49.760Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Main Cabin airport fees for tickets ticketed on or after 10 April 2026: 1st bag $35->$45, 2nd bag $45->$55, 3rd bag $200, 4th and each additional bag $200. A carry-on bag and a personal item are included.', datetime('now')),
  ('b6-bluebasic', 'b6', 'Blue Basic', 1, 1, 60, 75, 200, NULL, 0, NULL, 'https://news.jetblue.com/latest-news/press-release-details/2024/JetBlue-Gives-Blue-Basic-a-Boost-with-Complimentary-Carry-On-Bag-Starting-September-6/default.aspx', 'JetBlue – Blue Basic carry-on allowance', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Blue Basic includes a carry-on and a personal item for travel from September 6, 2024. Checked rates depend on dates and purchase timing.', datetime('now')),
  ('b6-blue', 'b6', 'Blue', 1, 1, 60, 75, 200, NULL, 0, NULL, 'https://www.jetblue.com/help/checked-bags', 'JetBlue - Checked bags', NULL, '2026-11-04T18:04:27.071Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Blue airport fees within 24 hours of departure on off-peak dates: 1st bag $35->$60, 2nd bag $50->$75. Peak dates are $70 and $85; prepaid more than 24 hours ahead it is $50 off-peak and $55 peak. The 3rd or more checked bag is $200. Blue includes a carry-on bag and a personal item.', datetime('now')),
  ('ba-economy', 'ba', 'Economy Standard', 1, 1, 0, NULL, NULL, NULL, 0, NULL, 'https://www.britishairways.com/content/information/help/faq/baggage/some-checked-in-and-some-not', 'British Airways – Basic and Standard checked baggage', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'British Airways World Traveller, London Heathrow to New York JFK, one way. Paid bags require an itinerary quote.', 'GBP', 'verified', 'World Traveller Basic is hand baggage only. Standard includes one hold bag. Extra bag prices depend on the itinerary.', datetime('now')),
  ('ba-economy-basic', 'ba', 'Economy Basic', 1, 1, NULL, NULL, NULL, NULL, 0, NULL, 'https://www.britishairways.com/content/information/help/faq/baggage/some-checked-in-and-some-not', 'British Airways – Basic and Standard checked baggage', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'British Airways World Traveller, London Heathrow to New York JFK, one way. Paid bags require an itinerary quote.', 'GBP', 'verified', 'World Traveller Basic is hand baggage only. Standard includes one hold bag. Extra bag prices depend on the itinerary.', datetime('now')),
  ('ac-basic', 'ac', 'Economy Basic', 1, 0, 45, 60, 100, NULL, 0, NULL, 'https://www.aircanada.com/us/en/aco/home/legal/products-and-services.html', 'Air Canada - Products and services (baggage)', NULL, '2026-11-04T18:07:17.776Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'Air Canada, mainland US to Canada, one way, published US-dollar base before tax. Excludes through international itineraries, status and cards. Basic restriction applies to tickets issued January 3, 2025 onward.', 'USD', 'verified', 'Economy Basic between Canada and the U.S.: 1st bag 45 USD (45-54 with tax), 2nd bag 60 USD (60-72), each additional bag 100 USD (100-120). Economy Basic includes a personal item but not a carry-on on most itineraries for tickets purchased on or after 3 January 2025.', datetime('now')),
  ('ac-main', 'ac', 'Economy Standard', 1, 1, 45, 60, 100, NULL, 0, NULL, 'https://www.aircanada.com/us/en/aco/home/legal/products-and-services.html', 'Air Canada - Products and services (baggage)', NULL, '2026-11-04T18:07:17.776Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'Air Canada, mainland US to Canada, one way, published US-dollar base before tax. Excludes through international itineraries, status and cards. Basic restriction applies to tickets issued January 3, 2025 onward.', 'USD', 'verified', 'Economy Standard between Canada and the U.S.: 1st bag 45 USD (45-54 with tax), 2nd bag 60 USD (60-72), each additional bag 100 USD (100-120). A carry-on bag and a personal item are included. Flex fares include the first bag free; Latitude includes two.', datetime('now')),
  ('ws-basic', 'ws', 'UltraBasic', 1, 0, NULL, NULL, NULL, NULL, 0, NULL, 'https://www.westjet.com/en-us/flights/fees', 'WestJet – fees by fare and purchase stage', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'WestJet-operated Canada/US travel, excluding Europe/Asia connections. Base fare without Extended Comfort. Obtain the bag price for your departure and payment stage.', 'USD', 'verified', 'Published bag and excess fees are ranges. Currency, tax, itinerary and payment stage affect the quote.', datetime('now')),
  ('ws-extended', 'ws', 'UltraBasic + Extended Comfort', 1, 1, NULL, NULL, NULL, NULL, 0, NULL, 'https://www.westjet.com/en-us/manage/extended-comfort', 'WestJet – Extended Comfort', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'WestJet-operated Canada/US travel with Extended Comfort purchased for the flight. Checked-bag prices vary.', 'USD', 'verified', 'A purchased Extended Comfort seat includes one personal item and one carry-on. Other bags follow the UltraBasic rules.', datetime('now')),
  ('ws-main', 'ws', 'Econo', 1, 1, NULL, NULL, NULL, NULL, 0, NULL, 'https://www.westjet.com/en-us/flights/fees', 'WestJet – fees by fare and purchase stage', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'WestJet-operated Canada/US travel, excluding Europe/Asia connections. Base fare without Extended Comfort. Obtain the bag price for your departure and payment stage.', 'USD', 'verified', 'Published bag and excess fees are ranges. Currency, tax, itinerary and payment stage affect the quote.', datetime('now')),
  ('lh-basic', 'lh', 'Economy Light', 1, 1, 90, 90, 300, NULL, 0, NULL, 'https://www.lufthansa.com/us/en/carry-on-baggage.html', 'Lufthansa – carry-on baggage by cabin', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'United States to Germany, Economy Class, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Long-haul Economy Light includes a personal item and one cabin bag up to 8 kg. The European Economy Basic restriction is a different fare. See https://www.lufthansa.com/us/en/current-fees for checked baggage.', datetime('now')),
  ('lh-main', 'lh', 'Economy (with checked allowance)', 1, 1, 0, 90, 300, NULL, 0, NULL, 'https://www.lufthansa.com/us/en/current-fees', 'Lufthansa - Current fees', NULL, '2026-11-04T17:57:36.481Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'United States to Germany, Economy Class, one-way, per passenger, paid at the airport', 'USD', 'verified', 'Economy Class on a United States to Germany itinerary: the first checked bag up to 23 kg is free, the second costs 90 USD at the airport, and each additional standard bag costs 300 USD at the check-in desk on long-haul intercontinental routes. A carry-on up to 8 kg and a personal item are included.', datetime('now')),
  ('ei-saver', 'ei', 'Saver (transatlantic)', 1, 1, 100, 100, NULL, NULL, 0, NULL, 'https://www.aerlingus.com/localized/en/modals/baggage-information.html', 'Aer Lingus – North America baggage rules', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'Transatlantic, one-way, per passenger (Aer Lingus prices bags by destination distance and by booking channel; the published 23 kg airport rate is recorded)', 'USD', 'verified', 'North America itineraries include one 10 kg cabin bag on Saver. The within-Europe check-in-or-pay rule has a different scope. Checked fees depend on weight, route and booking channel.', datetime('now')),
  ('sy-standard', 'sy', 'Base fare (no bundle)', 1, 0, NULL, NULL, NULL, NULL, 1, NULL, 'https://suncountry.com/bags-optional-services', 'Sun Country Airlines - Bags and Optional Services', NULL, '2026-11-04T18:22:01.745Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, one-way, per passenger, paid at the airport (Sun Country prices each bag for each flight, so it publishes no single base fee)', 'USD', 'verified', 'Sun Country publishes no single base bag price: its own page says bag prices vary by flight and sends travellers to Explore Bag Prices for the figure for their trip, and the carried-over figures had no source, so the base fee and the overhead carry-on fee are left unpriced and the calculator reports them as not priced. The under-seat item is included on every fare; the overhead bag is a paid add-on.', datetime('now')),
  ('ha-main', 'ha', 'Main Cabin', 1, 1, 45, 55, 200, NULL, 0, NULL, 'https://www.hawaiianairlines.com/content/travel-info/baggage/checked-bags', 'Alaska and Hawaiian – checked baggage', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'Alaska/Hawaiian North American flights ticketed on or after April 10, 2026. Excludes travel wholly within Hawaii and status or resident benefits.', 'USD', 'verified', 'Saver and Main both include a personal item and carry-on. The April 10 North America baggage schedule is $45, $55 and $200. Intra-Hawaii travel has separate rates.', datetime('now')),
  ('ha-basic', 'ha', 'Saver', 1, 1, 45, 55, 200, NULL, 0, NULL, 'https://www.alaskaair.com/content/travel-info/flight-experience/saver', 'Alaska and Hawaiian – Saver fare', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'Alaska/Hawaiian North American flights ticketed on or after April 10, 2026. Excludes travel wholly within Hawaii and status or resident benefits.', 'USD', 'verified', 'Saver and Main both include a personal item and carry-on. The April 10 North America baggage schedule is $45, $55 and $200. Intra-Hawaii travel has separate rates.', datetime('now')),
  ('g4-standard', 'g4', 'Base fare (no bundle)', 1, 0, NULL, NULL, NULL, NULL, 1, NULL, 'https://www.allegiantair.com/baggage-1', 'Allegiant Air - Carry-On and Checked Baggage Policy, Size & Fees', NULL, '2026-11-04T17:53:15.013Z', '2026-11-04', 'Mavis (M9 source verification pass)', 'US domestic, main-cabin economy, one-way, per passenger (Allegiant prices every bag for the route and the date, and its own calculator labels its figures estimates)', 'USD', 'verified', 'Allegiant publishes no fixed bag price: its own bag fee calculator produces per-route estimates and labels them as such. The base checked-bag fee and the carry-on fee are left unpriced and the calculator reports them as not priced. One personal item is included free; the carry-on and checked bags are paid add-ons.', datetime('now')),
  ('bz-standard', 'bz', 'No Flex (no bundle)', 1, 0, NULL, NULL, NULL, NULL, 1, NULL, 'https://www.flybreeze.com/fly-with-us/bundles', 'Breeze – flight bundles and fares', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'US domestic, main-cabin economy, one-way, per passenger (Breeze prices every bag for the booking session, so no single figure is published)', 'USD', 'verified', 'No Flex includes one personal item. Additional bags are optional and priced when booked.', datetime('now')),
  ('bz-nice', 'bz', 'Nice bundle', 1, 1, NULL, NULL, NULL, NULL, 0, NULL, 'https://www.flybreeze.com/fly-with-us/bundles', 'Breeze – flight bundles and fares', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'US domestic, main-cabin economy, one-way, per passenger (Breeze prices every bag for the booking session, so no single figure is published)', 'USD', 'verified', 'Includes one personal item, one carry-on and 0 checked bags. Other bags use the itinerary price.', datetime('now')),
  ('bz-nicer', 'bz', 'Nicer bundle', 1, 1, 0, NULL, NULL, NULL, 0, NULL, 'https://www.flybreeze.com/fly-with-us/bundles', 'Breeze – flight bundles and fares', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'US domestic, main-cabin economy, one-way, per passenger (Breeze prices every bag for the booking session, so no single figure is published)', 'USD', 'verified', 'Includes one personal item, one carry-on and 1 checked bags. Other bags use the itinerary price.', datetime('now')),
  ('bz-nicest', 'bz', 'Nicest bundle', 1, 1, 0, 0, NULL, NULL, 0, NULL, 'https://www.flybreeze.com/fly-with-us/bundles', 'Breeze – flight bundles and fares', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'US domestic, main-cabin economy, one-way, per passenger (Breeze prices every bag for the booking session, so no single figure is published)', 'USD', 'verified', 'Includes one personal item, one carry-on and 2 checked bags. Other bags use the itinerary price.', datetime('now')),
  ('av-standard', 'av', 'Base fare (no bundle)', 1, 0, NULL, NULL, NULL, NULL, 1, NULL, 'https://www.aveloair.com/optional-services', 'Avelo – optional services', NULL, '2026-11-06T02:59:27Z', '2026-11-06', 'Oak & Main policy review (Codex)', 'US domestic base fare, one way. Individual bag prices vary by itinerary and purchase time.', 'USD', 'verified', 'Base ticket includes one personal item. Additional bags have a range of prices, depending on the flight and time of purchase. Use the airline quote for the base fee.', datetime('now'));

